}
.btn-danger:hover {
  background: #4a1a1f;
  border-color: var(--danger);
  color: #fff;
}

.btn-danger-solid {
  background: var(--danger);
  border-color: var(--danger);
  color: #1a0608;
  font-weight: 600;
}
.btn-danger-solid:hover {
  background: var(--danger-hover);
  border-color: var(--danger-hover);
  color: #1a0608;
}

.btn-ghost {
  background: transparent;
  border-color: var(--border-strong);
  color: var(--text);
}
.btn-ghost:hover {
  background: var(--bg-3);
}

